        assert_eq!(disk_preflight(state_bytes, 128).unwrap(), 174_862_106_624);
        #[cfg(feature = "n512-m512-piecewise-cadv33")]
        assert_eq!(disk_preflight(3_233_808_384, 48).unwrap(), 155_226_537_984);
    }

    #[cfg(feature = "n512-m512-piecewise-cadv33")]
    #[test]
    fn captured_actual_state_has_no_inline_observer_claim() {
        let root = root("captured");
        let state = state();
        stage_step(
            &root,
            8,
            &state,
            Observation::Captured {
                identity: "identity",
                offline_observer_node: true,
            },
            "{\"outcome\":\"committed\"}\n",
        )
        .unwrap()
        .publish()
        .unwrap();
        let record = fs::read_to_string(root.join("step-008-clock-0000/record.json")).unwrap();
        assert!(record.contains("\"observation_status\": \"CapturedActualState\""));
        assert!(record.contains("\"observer_execution\": \"offline-baccus-required\""));
        assert!(record.contains("\"offline_observer_node\": true"));
        assert!(record.contains("\"qualification\": false"));
        assert!(!record.contains("\"balance\""));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn rest_is_metadata_only_and_unscheduled_step_has_no_balance() {
        let root = root("unscheduled");
        publish_rest(&root, "identity").unwrap();
        assert!(!root.join("state.bin").exists());
        let state = state();
        stage_step(
            &root,
            1,
            &state,
            Observation::NotScheduled {
                identity: "identity",
            },
            "{\"outcome\":\"committed\"}\n",
        )
        .unwrap()
        .publish()
        .unwrap();
        let bundle = root.join("step-001-clock-0000");
        let record = fs::read_to_string(bundle.join("record.json")).unwrap();
        assert!(record.contains("\"observation_status\": \"NotScheduled\""));
        assert!(!record.contains("\"balance\""));
        assert!(bundle.join("state.bin").exists());
        assert!(bundle.join("attempt.json").exists());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn scheduled_step_carries_actual_balance_in_same_bundle() {
        let root = root("scheduled");
        let state = state();
        let record = NodeRecord {
            identity: "identity",
            balance: BalanceSample::REST,
            observer_seconds: 1.0,
            force_seconds: 0.5,
            conservative_seconds: 0.25,
            transfer_measure_seconds: 0.25,
        };
